  insert into public.brands (name, website, description, country, status) values ('Nam Botanica', 'https://nambotanica.com', 'Practitioner-formulated herbal self-care brand founded by Mimi, built around botanical teas and plant-based skin and hair topicals. Its own Affiliate Program page offers 10% commission on every referred order through UpPromote, with a personal link, exclusive discount codes and early product access. The page states the cap explicitly twice — ''No cap'' on the commission and ''There''s no ceiling on your earnings'' — so commission_cap is recorded as verified uncapped.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'UpPromote', 10, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://nambotanica.com/pages/affiliate-program.', 'https://nambotanica.com/pages/affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Nam Botanica Affiliate Program', 'https://nambotanica.com/pages/affiliate-program', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://nambotanica.com/pages/affiliate-program', 'brand_site', 'affiliate_program', 'Nam Botanica''s own Affiliate Program page (''Earn 10% on every sale you refer'') routes applications to its UpPromote portal (af.uppromote.com). It welcomes creators, practitioners, bloggers and podcasters, is free to join, and applications are reviewed within 3–5 business days.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://nambotanica.com/pages/affiliate-program', 'brand_site', 'commission_cap', 'The brand''s own page states the cap explicitly: ''Every customer you refer earns you a 10% commission on their order. No cap, no minimum threshold to get started'' and, under Grow with us, ''The more you share, the more you make. There''s no ceiling on your earnings'' — so commission_cap is recorded as uncapped. No absolute creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://nambotanica.com/pages/about', 'brand_site', 'brand_background', 'The brand''s About page describes founder Mimi''s background in nutrition and Chinese Medicine and the product lines: organic herbal teas plus plant-based skin topicals and hair topicals.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 20, 15, 16, 7, 8, 3, '{"niche_fit": "Botanical skin topicals, hair topicals and ritual-style herbal self-care fit natural-beauty and wellness UGC well, though the range is narrower than core skincare.", "ugc_evidence": "The program explicitly recruits content creators, bloggers and podcasters, with a personal tracked link, audience discount codes and early product access.", "compensation": "10% on every order with an explicit no-cap / no-ceiling statement on the brand''s own page \u2014 verified uncapped.", "contact_access": "Application runs through the brand''s own page into UpPromote; no public program email is published.", "opportunity_availability": "Free and publicly open to apply; the brand states it responds within 3\u20135 business days and values authenticity over audience size.", "credibility": "Small, young practitioner-led brand with a real storefront and a detailed program page, but limited track record."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Laka', 'https://lakaflow.com', 'Hawaiian wellness brand (''Best on Earth supplements, movement, and skincare'') selling adaptogen and superfood blends and skincare. Its own affiliate page publishes a tiered program — Starter 10% (0–10 sales/month), Builder 15%, Partner 20% — covering subscriptions and repeat orders, with no follower minimum, and its FAQ answers the earnings question with ''There''s no cap'', so commission_cap is recorded as verified uncapped.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'wellness'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'affiliates@lakaflow.com', null, null, 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct (Laka Affiliate Program)', 10, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://lakaflow.com/pages/fruiting.', 'https://lakaflow.com/pages/fruiting', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Laka Affiliate Program', 'https://lakaflow.com/pages/fruiting', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://lakaflow.com/pages/fruiting', 'brand_site', 'affiliate_program', 'Laka''s own affiliate page publishes the tiers: Starter 10% commission (0–10 sales/month), Builder 15% (11–25), Partner 20% (26+), on all sales including subscriptions and repeat orders, with a unique audience discount code, tracking dashboard, marketing assets, monthly payouts and a $50 minimum payout. The 10% starting tier is recorded as the rate.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://lakaflow.com/pages/fruiting', 'brand_site', 'commission_cap', 'The brand''s own page states the cap explicitly twice: ''No follower minimum. No sales cap.'' and the FAQ answer to ''How much can I earn?'' is ''There''s no cap. Your earnings depend on how much you share and how engaged your audience is'' — so commission_cap is recorded as uncapped. No absolute creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 19, 14, 17, 13, 9, 3, '{"niche_fit": "Adaptogen blends and skincare-adjacent wellness products suit wellness and beauty-from-within creators, though supplements lead the range rather than skincare.", "ugc_evidence": "A creator-facing program with a custom dashboard, marketing assets, content ideas and early launch access; no follower minimum.", "compensation": "10% starting commission tiering to 20%, paid on repeat and subscription orders, with an explicit ''There''s no cap'' FAQ answer on the brand''s own page \u2014 verified uncapped.", "contact_access": "A dedicated affiliates@ email is published on the program page alongside the application.", "opportunity_availability": "Publicly open with no follower minimum; engagement and alignment matter more than audience size.", "credibility": "Operating DTC brand with a full storefront and detailed program terms, but a small, single-brand operation."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Starface', 'https://starface.world', 'Gen-Z skincare brand known for Hydro-Stars hydrocolloid pimple patches. Its own UK site carries a Starface Affiliate Partners page: free to apply and join on Impact Radius and GRIN, with exclusive promotions and a commission described only as ''up to 10%'' — an up-to ceiling with no published base rate — so commission_rate is recorded as null. No cap statement is published.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'skincare'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'hello@starfaceworld.com', null, null, 'needs_review', null);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', 'influencers@starfaceworld.com', null, null, 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://starfaceworld.co.uk/pages/affliate.', 'https://starfaceworld.co.uk/pages/affliate', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Starface Affiliate Partners (Impact / GRIN)', 'https://starfaceworld.co.uk/pages/affliate', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://starfaceworld.co.uk/pages/affliate', 'brand_site', 'affiliate_program', 'Starface''s own UK site carries a ''Starface Affiliate Partners'' page aimed at publishers, PR and influencers: ''Free to apply + join on Impact Radius and Grin'', with exclusive access to new launches and promotions.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://starfaceworld.co.uk/pages/affliate', 'brand_site', 'commission_rate', 'The brand''s own page describes the pay only as ''Up to 10% commision — Earn a competitive commission rate, up to 10%''. An up-to figure is a ceiling, not a base rate, so commission_rate is recorded as null. No source publishes an earnings cap statement or absolute creator counts, so commission_cap and creator_saturation stay unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://usesnippet.app/pr-emails/starface', 'affiliate_directory', 'contact', 'A November 12, 2026 check of Starface''s own pages records the brand listing influencers@starfaceworld.com for influencers, press@starfaceworld.com for PR and hello@starfaceworld.com for partnerships.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 14, 8, 12, 7, 5, '{"niche_fit": "Hydro-Stars pimple patches are made for visual, Gen-Z skincare UGC \u2014 patch reveals, routines and acne journeys.", "ugc_evidence": "The brand runs affiliate partners through Impact and the creator platform GRIN and is heavily creator-led on social, though its own program page is brief.", "compensation": "Only an ''up to 10%'' ceiling is published with no base rate, so the rate is null and compensation is scored cautiously; cap unknown.", "contact_access": "Published influencer and partnerships emails plus application routes via Impact and GRIN.", "opportunity_availability": "Free to apply through the brand''s affiliate page and networks.", "credibility": "Established, widely retailed skincare brand founded in 2019 with major press and retail distribution."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Hero Cosmetics', 'https://herocosmetics.us', 'Acne-care brand founded in 2017 by Ju Rhyu, maker of the Mighty Patch hydrocolloid acne patches. Its affiliate route is a Sovrn Commerce merchant listing quoting ''up to 8%'' with a 30-day cookie, while a second directory claims a 15% payout — the published figures conflict, so commission_rate is recorded as null. A November 2026 check found no affiliate program published on the brand''s own pages, only a creator interest form. No cap statement is published.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'skincare'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Sovrn Commerce', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://merchants.sovrn.com/merchants/138869/herocosmetics-us-affiliate-program.', 'https://merchants.sovrn.com/merchants/138869/herocosmetics-us-affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Hero Cosmetics Affiliate Program (Sovrn Commerce)', 'https://merchants.sovrn.com/merchants/138869/herocosmetics-us-affiliate-program', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://merchants.sovrn.com/merchants/138869/herocosmetics-us-affiliate-program', 'affiliate_directory', 'affiliate_program', 'Sovrn Commerce''s merchant page for HeroCosmetics.us describes the affiliate program with a commission rate of up to 8% on sales and a 30-day cookie, noting that specific rates vary by product category and promotional period and are confirmed inside the Sovrn dashboard.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://admin.shopper.com/partnerships/herocosmetics-us-affiliate-program', 'affiliate_directory', 'commission_rate', 'Shopper''s Hero Cosmetics listing instead claims a payout rate of 15% per sale. That conflicts with Sovrn''s up-to-8% figure, so commission_rate is recorded as null rather than guessed. A November 12, 2026 check of the brand''s own pages (usesnippet.app/pr-emails/hero-cosmetics) found no affiliate program published there — only a creator interest form — and no source publishes an earnings cap statement or absolute creator counts, so commission_cap and creator_saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 12, 7, 5, 6, 5, '{"niche_fit": "Mighty Patch is one of the most demonstrable acne products in skincare UGC \u2014 overnight patch results are a staple format.", "ugc_evidence": "A Sovrn merchant route plus a brand-run creator interest form and an active creator community (Hero Skin Squad), though no program is published on the brand''s own pages.", "compensation": "Published figures conflict (up to 8% vs 15%), so the rate is recorded as null and compensation scored down; cap unknown.", "contact_access": "No public program email is published; contact runs through Sovrn or the brand''s creator interest form.", "opportunity_availability": "Joinable through Sovrn Commerce, subject to that network''s merchant access and approval.", "credibility": "Category-leading acne brand founded in 2017, sold at Target, Ulta and Amazon with extensive press."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Peace Out Skincare', 'https://peaceoutskincare.com', 'Dermatologist-developed acne and pore-care brand (acne dots, pore strips, serums). Affiliate directories publish three different figures for its program — 5% per sale in one, up to 3.33% in another and a 0.8% publisher payout in a third — so commission_rate is recorded as null with the conflict documented. Its program feeds run through affiliate networks including Rakuten. No cap statement is published.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'skincare'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Affiliate network (directory-listed)', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://getlasso.co/affiliate/peace-out-skincare/.', 'https://getlasso.co/affiliate/peace-out-skincare/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Peace Out Skincare Affiliate Program', 'https://getlasso.co/affiliate/peace-out-skincare/', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/peace-out-skincare/', 'affiliate_directory', 'commission_rate', 'Lasso''s Peace Out Skincare listing records the affiliate program at 5% commission per sale in the Beauty category.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://admin.shopper.com/partnerships/peaceoutskincare-com-affiliate-program', 'affiliate_directory', 'commission_rate', 'Shopper''s Peace Out listing instead records up to 3.33% per sale, and FlexOffers lists a 0.8% publisher payout with a 30-day cookie. Three published figures (5%, up to 3.33%, 0.8%) across different network routes cannot settle a single rate, so commission_rate is recorded as null. DailyCashback''s merchant feed attributes the program to the Rakuten affiliate network. No source publishes an earnings cap statement or absolute creator counts, so commission_cap and creator_saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 11, 7, 5, 7, 4, '{"niche_fit": "Acne dots and pore strips are visual, problem-solution products that map directly onto skincare UGC formats.", "ugc_evidence": "Directory-listed affiliate routes with tracked links; the brand is social-active but publishes no creator program page of its own.", "compensation": "Three directories publish three different figures, so the rate is null and compensation scored down for uncertainty; cap unknown.", "contact_access": "No public program email is published; access runs through the network listings.", "opportunity_availability": "Listed across several affiliate networks and directories as joinable.", "credibility": "Established acne-care brand with Sephora distribution and a long press trail; only the rate documentation is inconsistent."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Pixi Beauty', 'https://www.pixibeauty.com', 'UK beauty company founded by Petra Strand, known for Glow Tonic and fuss-free multitasking skincare and makeup. Two affiliate directories agree its program runs on ShareASale at 5% commission per sale with a 60-day cookie; a separate publisher network lists different new/existing customer terms, documented in the evidence. No cap statement is published, so the cap stays unknown.', 'United Kingdom', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'ShareASale', 5, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://getlasso.co/affiliate/pixi-beauty/.', 'https://getlasso.co/affiliate/pixi-beauty/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Pixi Beauty Affiliate Program', 'https://getlasso.co/affiliate/pixi-beauty/', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/pixi-beauty/', 'affiliate_directory', 'affiliate_program', 'Lasso''s Pixi Beauty listing records the affiliate program in the Beauty, Makeup and Skin Care categories at 5% commission per sale with a 60-day cookie duration.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.affilorama.com/blog/best-beauty-affiliate-programs', 'affiliate_directory', 'commission_rate', 'Affilorama''s beauty affiliate program list independently records Pixi Beauty at 5% commission, a 60-day cookie and the ShareASale network — agreeing with Lasso''s figure, so 5% via ShareASale is recorded. FlexOffers lists a different publisher structure (8% new customers / 4% existing) on its own route; that is a sub-network payout split, not the merchant''s ShareASale rate. No source publishes an earnings cap statement or absolute creator counts, so commission_cap and creator_saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 12, 10, 5, 7, 5, '{"niche_fit": "Glow Tonic and multitasking makeup are long-running staples of skincare and everyday-beauty UGC.", "ugc_evidence": "A network-run ShareASale program with tracked links and a long cookie; the brand also runs creator gifting through platforms like ShopMy, though no own creator program page is published.", "compensation": "5% per sale is modest but corroborated by two directories; no cap statement is published, so the cap is honestly unknown.", "contact_access": "No public program email is published; contact runs through the ShareASale application.", "opportunity_availability": "Open application through ShareASale.", "credibility": "Established UK beauty company with global retail distribution and a decades-long track record."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Florence by Mills', 'https://florencebymillsbeauty.com', 'Gen-Z beauty and skincare brand founded by Millie Bobby Brown. The affiliate network feed records a live ''florence by mills beauty'' merchant program on ShareASale (merchant #154835, Health & Beauty), but no commission rate is published in any fetched source, so commission_rate is recorded as null. The brand''s own pages publish no program or PR email, and the brand has promoted a ''flo squad'' ambassador community offering commission. No cap statement is published.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'ShareASale', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.fmtc.co/new-fmtc-merchants-include-clicks-florence-by-mills-beauty-little-planet-neon-earth-amp-ultimate-nutrition/.', 'https://www.fmtc.co/new-fmtc-merchants-include-clicks-florence-by-mills-beauty-little-planet-neon-earth-amp-ultimate-nutrition/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Florence by Mills Affiliate Program (ShareASale)', 'https://www.fmtc.co/new-fmtc-merchants-include-clicks-florence-by-mills-beauty-little-planet-neon-earth-amp-ultimate-nutrition/', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.fmtc.co/new-fmtc-merchants-include-clicks-florence-by-mills-beauty-little-planet-neon-earth-amp-ultimate-nutrition/', 'affiliate_directory', 'affiliate_program', 'FMTC''s new-merchant listing records ''florence by mills beauty'' as a merchant on ShareASale (#154835) in the Health & Beauty category with a network signup route. No commission rate is published in the listing, so commission_rate is recorded as null.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://usesnippet.app/pr-emails/florence-by-mills', 'affiliate_directory', 'affiliate_program', 'A November 16, 2026 check of the brand''s own pages found no PR email, form or creator program published there — the program surface is the ShareASale merchant listing plus the brand''s ''flo squad'' ambassador community, which its Instagram promotion describes as offering free products, discounts and commission. No source publishes an earnings cap statement or absolute creator counts, so commission_cap and creator_saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 7, 5, 6, 4, '{"niche_fit": "Clean Gen-Z skincare and makeup from a celebrity-founded brand is highly shareable beauty UGC material.", "ugc_evidence": "A live ShareASale merchant program plus a promoted ambassador community (''flo squad'') offering commission and reposts, though the brand publishes no program page of its own.", "compensation": "No rate is published anywhere fetched, so the rate is null and compensation scored cautiously; cap unknown.", "contact_access": "No public program or PR email is published; access runs through ShareASale.", "opportunity_availability": "Listed as a live ShareASale merchant; application runs through the network.", "credibility": "Well-known brand with national retail (Ulta) and a large social following; only program documentation is thin."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('about-face', 'https://aboutface.com', 'Color cosmetics brand founded by Halsey, built on bold, long-wearing, cruelty-free makeup for creative self-expression. An affiliate directory records its program on ShareASale at 5% commission per sale with a 15-day cookie, open to all regions (listing last updated March 2024). No cap statement is published, so the cap stays unknown.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'ShareASale', 5, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://linkclicky.com/affiliate-program/about-face/.', 'https://linkclicky.com/affiliate-program/about-face/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'about-face Affiliate Program', 'https://linkclicky.com/affiliate-program/about-face/', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/about-face/', 'affiliate_directory', 'affiliate_program', 'LinkClicky''s about face listing (last updated March 10, 2024) records the brand''s website as aboutface.com, the affiliate platform as ShareASale, open to all regions, with a 15-day cookie and commission of 5% per sale, described as what''s officially listed with the affiliate program as the payout. No source publishes an earnings cap statement or absolute creator counts, so commission_cap and creator_saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 11, 10, 5, 7, 4, '{"niche_fit": "Bold, editorial color cosmetics are strong material for creative makeup UGC and transformation content.", "ugc_evidence": "A network-run ShareASale program with tracked links; the brand is creator- and artistry-led on social, but no creator program page is published.", "compensation": "5% per sale is modest; the single directory record dates from March 2024, so the rate should be re-confirmed in the network. Cap unknown.", "contact_access": "No public program email is published; contact runs through the ShareASale application.", "opportunity_availability": "Open application through ShareASale, listed for all regions.", "credibility": "Established celebrity-founded brand with Ulta distribution; program documentation rests on one directory listing."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('MasterPeace Body Therapy', 'https://www.masterpeacebodytherapy.com', 'Luxury bath and body brand — Iyanla Vanzant''s MasterPeace line of bar soaps, body wash, body butters and salt scrubs. An affiliate directory records its program at 5% commission per sale with the join route on ShareASale, in the Beauty category. No cap statement is published, so the cap stays unknown.', 'United States', 'published') returning id into bid;
