  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/masterpeace-body-therapy/', 'affiliate_directory', 'affiliate_program', 'Lasso''s MasterPeace Body Therapy listing records the affiliate program at 5% commission per sale in the Beauty, Health and Wellness and Hygiene categories, with the join link routing to ShareASale.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://masterpeacebodytherapy.com', 'brand_site', 'brand_background', 'The brand''s official site presents MasterPeace as Iyanla Vanzant''s bath and body line (bar soaps, body wash, body butters, salt scrubs, room sprays), sells in USD with US shipping terms, and publishes the contact email shop@masterpeacebodytherapy.com. No source publishes an earnings cap statement or absolute creator counts, so commission_cap and creator_saturation stay unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 18, 10, 10, 9, 7, 3, '{"niche_fit": "Bath and body rituals fit self-care UGC, though the niche is narrower than skincare or makeup.", "ugc_evidence": "A standard ShareASale affiliate program; no creator-specific program details, gifting or content perks are published.", "compensation": "5% per sale is modest; no cap statement is published, so the cap is honestly unknown.", "contact_access": "A contact email is published on the brand''s own site, and application runs through ShareASale.", "opportunity_availability": "Open application through ShareASale.", "credibility": "Small celebrity-fronted bath brand with a real storefront; program rests on a single directory listing."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('F. Miller', 'https://fmillerskincare.com', 'Premium botanical skincare brand built around plant-based face oils and minimalist formulas. A directory listing for its US program describes the payout only as ''up to 5-10% per sale'' — a range with an up-to ceiling and no single published base rate — so commission_rate is recorded as null. No cap statement is published.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'skincare'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Affiliate network (directory-listed)', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.shopper.com/partnerships/fmillerskincare-com-affiliate-program.', 'https://www.shopper.com/partnerships/fmillerskincare-com-affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'F. Miller Affiliate Program', 'https://www.shopper.com/partnerships/fmillerskincare-com-affiliate-program', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shopper.com/partnerships/fmillerskincare-com-affiliate-program', 'affiliate_directory', 'affiliate_program', 'Shopper''s F. Miller US listing records the affiliate and partnership program with a payout described as ''up to 5-10% per sale''. A range under an up-to ceiling cannot settle a single base rate, so commission_rate is recorded as null. No source publishes an earnings cap statement or absolute creator counts, so commission_cap and creator_saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 10, 7, 5, 6, 4, '{"niche_fit": "Minimalist botanical face oils are premium, ritual-led material for skincare UGC.", "ugc_evidence": "A directory-listed affiliate program with tracked links; no creator-specific program page is published by the brand.", "compensation": "Only an up-to range (5-10%) is published with no base rate, so the rate is null and compensation scored cautiously; cap unknown.", "contact_access": "No public program email is published; access runs through the network listing.", "opportunity_availability": "Listed as joinable through its affiliate network listing.", "credibility": "Established premium botanical brand with editorial press and boutique retail presence; program documentation is thin."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Sports Gear Swag', 'https://www.sportsgearswag.ca', 'Custom team sports apparel brand whose own affiliate program is built for sports coaches, trainers, athletes, sports influencers and fitness content creators. Its published program terms carry an explicit no-cap earnings statement — a verified-uncapped program — plus a $25 bonus for a first Reel or TikTok posted within 7 days of approval; the brand''s own pages conflict on the commission rate itself (10%/5% in the terms versus 15% on its affiliate landing page), so no rate is recorded.', 'Canada', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fitness'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'sales@sportsgearswagpromo.com', null, 'https://www.sportsgearswagpromo.com/affiliate-program-terms', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', null, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://www.sportsgearswagpromo.com/affiliate-program-terms.', 'https://www.sportsgearswag.ca/affiliate', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Sports Gear Swag Affiliate Program', 'https://www.sportsgearswag.ca/affiliate', 'https://www.sportsgearswagpromo.com/affiliate-program-terms', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.sportsgearswagpromo.com/affiliate-program-terms', 'official_program_page', 'commission_cap', 'The brand''s own Affiliate Program Terms & Requirements (last updated September 2026), section 8 ''Commission Structure & Tracking'': ''No Commission Cap: There is no limit to the total amount of commission you can earn.'' — an explicit no-limit earnings statement in the brand''s own program terms, so commission_cap is uncapped. The same section sets a milestone bonus of ''$100 in SGS Rewards'' at $1,000 in total referred sales — that bonus is paid in store credit; the commission itself is paid out in money (payouts issued by check once the approved balance reaches $100).', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.sportsgearswag.ca/affiliate', 'official_program_page', 'commission_rate_conflict', 'The brand''s own pages conflict on the rate: the Terms (section 8) set 10% commission on first-time purchases and 5% recurring commission on repeat purchases, while the brand''s own affiliate landing page advertises ''15% commission on every sale'' (first orders and repeat purchases alike), a $25 first approved video payment and a ''+$100 Cash Bonus at $1,000 in Sales'' (the Terms describe that $100 as SGS Rewards credit). Because the brand''s own two pages conflict, commission_rate is null. The Terms state the program ''is designed for sports coaches, trainers, athletes, sports influencers, fitness and athletic content creators, club organizers, team managers, and sports organizations'', require 1-2 posts per month to stay active, and publish the Affiliate Relations contact sales@sportsgearswagpromo.com.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 18, 13, 12, 9, 3, '{"compensation": "Verified-uncapped earnings with an explicit ''No Commission Cap'' statement in the brand''s own terms \u2014 but the brand''s own pages conflict on the rate (10% first / 5% repeat in the terms versus 15% flat on its landing page), so no rate is recorded; the $100 payout threshold and payment by mailed check also temper the score.", "contact_access": "The terms publish a named Affiliate Relations email (sales@sportsgearswagpromo.com), a toll-free phone number and 24/7 live chat \u2014 unusually direct contact access.", "credibility": "A small, niche custom team-apparel operation rather than an established national brand, though its program terms are detailed and current (updated September 2026).", "niche_fit": "Custom team jerseys, uniforms and athletic apparel are natural content for sports, coaching and fitness creators \u2014 team reveals, gear reviews and game-day content.", "opportunity_availability": "Open application with review typically within 1-3 business hours per the terms; staying active requires 1-2 posts per month, which is scored in.", "ugc_evidence": "A creator-first program by design: it recruits sports influencers and content creators by name, pays a $25 bonus for a first Reel/TikTok within 7 days of approval, and its terms include a full UGC usage-rights section for tagged content."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Barbell Apparel', 'https://barbellapparel.com', 'Athletic apparel brand built for lifters — jeans, shorts and training apparel cut for athletic builds. Its own Ambassador Division is a creator program for motivated athletes and influencers: the brand''s own program page states members earn 20% commission on referred sales, with no formal requirements and an application through the brand''s own link.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 20, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://barbellapparel.com/pages/barbell-ambassador-division.', 'https://barbellapparel.com/pages/barbell-ambassador-division', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Barbell Apparel Ambassador Division', 'https://barbellapparel.com/pages/barbell-ambassador-division', 'https://barbellapparel.com/pages/barbell-ambassador-division', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://barbellapparel.com/pages/barbell-ambassador-division', 'official_program_page', 'creator_program', 'The brand''s own Ambassador Division page: ''Earn 20% Commission. Members earn 20% commission on referred sales. Our top ambassadors earn thousands of dollars a month - and are often able to turn their fitness presence into a part or even full time income.'' The program looks for ''motivated athletes and influencers'', states ''There are no formal requirements'', and applications run through the brand''s own application link (barbellapparel.refunnel.app). No earnings-cap statement is published, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shopper.com/partnerships/barbellapparel-com-affiliate-program', 'third_party_directory', 'commission_rate_conflict', 'Shopper''s generic aggregator listing shows ''up to 5-10% payout per sale'' for Barbell Apparel, which conflicts with the 20% stated on the brand''s own program page; the brand''s own published figure governs and is the recorded rate, with the aggregator discrepancy noted here.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 17, 17, 5, 8, 4, '{"compensation": "A brand-published 20% commission on referred sales \u2014 among the strongest rates in this round; a generic aggregator lists a lower 5-10%, noted in evidence, but the brand''s own page governs. No cap statement is published.", "contact_access": "Application is through the brand''s own ambassador form; no partnerships email is published on the fetched page.", "credibility": "An established direct-to-consumer athletic apparel brand with a long-running ambassador program.", "niche_fit": "Apparel cut for athletic builds sits at the centre of lifting and fitness-fashion content \u2014 fit checks, training outfits and jean hauls for muscular frames.", "opportunity_availability": "Open application with no formal requirements, though the brand notes not everyone is accepted.", "ugc_evidence": "A dedicated ambassador program recruiting athletes and influencers by name, with monthly staff support emails and tips from top-performing ambassadors \u2014 a structured creator track, not a plain affiliate listing."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('GRAYL', 'https://grayl.com', 'Water purification and filtration bottle brand for travellers and outdoor users — press-to-purify bottles that make clean drinking water anywhere. Its affiliate program runs on AvantLink: the brand''s own affiliate page publishes commission rates starting at 8% with a 30-day cookie and a $105 average order size.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'AvantLink', 8, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://grayl.com/pages/affiliate-program.', 'https://grayl.com/pages/affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'GRAYL Affiliate Program (AvantLink)', 'https://grayl.com/pages/affiliate-program', 'https://grayl.com/pages/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://grayl.com/pages/affiliate-program', 'official_program_page', 'affiliate_program', 'The brand''s own affiliate page: ''Grayl has partnered with AvantLink, the leader in affiliate technology, to provide a robust affiliate program for your website... you can earn commissions by driving traffic from your site to grayl.com.'' Published program highlights: ''Commission rates starting at 8%'', ''30-day cookie'', ''Average order size of $105'', dedicated program management and support, and a professional video library for affiliates. The published 8% starting rate is recorded. No earnings-cap statement is published, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/grayl/', 'third_party_directory', 'affiliate_program', 'Lasso''s program listing independently reports the GRAYL affiliate program at ''8% Per Sale'' with a 30-day cookie, agreeing with the brand''s published starting rate.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 13, 4, 8, 4, '{"compensation": "A brand-published starting rate of 8% with a 30-day cookie on a $105 average order \u2014 solid for travel gear; the page frames 8% as a starting rate, so established affiliates may earn more. No cap statement is published.", "contact_access": "No partnerships email is published on the fetched page \u2014 joining is through AvantLink with dedicated program management after approval.", "credibility": "A well-reviewed specialist brand with thousands of customer reviews and a 10-year warranty, per its own affiliate page.", "niche_fit": "Purifier bottles are staple travel and backpacking content \u2014 destination water safety, gear lists and field tests map directly to travel creator feeds.", "opportunity_availability": "Free AvantLink account and application with brand approval.", "ugc_evidence": "The brand supports affiliates with content resources \u2014 blogs, social and YouTube channels, studio photography and a professional video library \u2014 though the program is framed for websites rather than a structured UGC track."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Pakt', 'https://www.paktbags.com', 'Minimalist travel gear brand for environmentally conscious travellers — the Pakt One carry-on and modular travel bags. Its affiliate program runs on Awin: the brand''s own FAQ advertises 15% commission with a 30-day cookie, while its own Awin merchant profile describes a starting commission of 10%, so no single rate is recorded.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://pakt-faqs.gorgias.help/en-US/articles/about-pakt-8929.', 'https://ui.awin.com/merchant-profile/77290', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Pakt Affiliate Program (Awin)', 'https://ui.awin.com/merchant-profile/77290', 'https://pakt-faqs.gorgias.help/en-US/articles/about-pakt-8929', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://pakt-faqs.gorgias.help/en-US/articles/about-pakt-8929', 'official_program_page', 'affiliate_program', 'The brand''s own FAQ: ''Do you have an affiliate program? Yes. 15% commission, a 30-day cookie, and product imagery for your channels. Sign up through Awin: https://ui.awin.com/merchant-profile/77290.'' The same FAQ states Pakt loves hearing from content creators but is ''not taking on UGC or one-off paid collaborations at the moment'', while ''our affiliate program is open to anyone and pays commission on what you sell''. A companion brand help page cites the same 15% commission with a $220+ average order value. No earnings-cap statement is published, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/77290?setLocale=da_DK', 'network_profile', 'commission_rate_conflict', 'The brand''s own Awin merchant profile describes the program structure as ''Earn Competitive Commissions - Starting commission of 10%'' with a ''30-Day Cookie Window'' — a starting rate that conflicts with the 15% headline in the brand''s own FAQ. Because the brand''s own sources conflict, commission_rate is null.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 10, 12, 4, 8, 4, '{"compensation": "Published figures are strong \u2014 15% in the brand''s FAQ against a ''starting commission of 10%'' on its own Awin profile, on a $220+ average order value \u2014 but because the brand''s own sources conflict, no rate is recorded and compensation scores cautiously. No cap statement is published.", "contact_access": "No partnerships email is published in the fetched sources \u2014 joining is through the Awin application.", "credibility": "An established minimalist travel-gear brand with a flagship carry-on and a lifetime warranty, per its own help pages.", "niche_fit": "Carry-on packing, one-bag travel and minimalist gear content are core travel-creator formats, and Pakt''s bags are built for exactly that audience.", "opportunity_availability": "The brand states the affiliate program is open to anyone via Awin sign-up.", "ugc_evidence": "The brand explicitly courts content creators in its FAQ and provides product imagery for channels, but states it is not taking on UGC or one-off paid collaborations at the moment \u2014 the affiliate program is the route in."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('YETI', 'https://www.yeti.com', 'Premium outdoor brand founded in 2006 — hard and soft coolers, drinkware, bags and outdoor living gear. Its affiliate program runs on Impact; published rates conflict widely across sources (4%, 5% and up to 15% all appear), so no rate is recorded.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://getlasso.co/affiliate/yeti/.', 'https://app.impact.com/campaign-promo-signup/YETI-US.brand', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'YETI Affiliate Program (Impact)', 'https://app.impact.com/campaign-promo-signup/YETI-US.brand', 'https://getlasso.co/affiliate/yeti/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/yeti/', 'third_party_directory', 'affiliate_program', 'Lasso''s program listing places YETI on Impact at ''4% Per Sale'' with a 30-day cookie and a $10 payout threshold; a creator-program guide publishes the Impact sign-up route (app.impact.com/campaign-promo-signup/YETI-US.brand). No earnings-cap statement is published, so commission_cap is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://uppromote.com/affiliate-programs/camping/', 'third_party_directory', 'commission_rate_conflict', 'Published rates conflict: UpPromote''s camping roundup reports YETI at 5% commission via Impact with a 30-day cookie and a $50 payment threshold, while other roundups claim up to 15% for top performers and an AvantLink listing shows up to 7%. Because the figures conflict across sources and the brand publishes no rate on a fetched brand page, commission_rate is null.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 11, 8, 4, 7, 5, '{"compensation": "Published figures conflict widely (4% via Impact per Lasso, 5% per UpPromote, up to 15% claimed elsewhere) and the brand publishes no rate on a fetched page, so no rate is recorded and compensation scores low; no cap statement is published.", "contact_access": "No partnerships email is published in the fetched sources \u2014 joining is through the Impact application.", "credibility": "One of the world''s most recognised premium outdoor brands, founded in 2006, with a cult following for its coolers and drinkware.", "niche_fit": "Coolers, drinkware and outdoor gear are staples of camping, road-trip, fishing and overlanding creator content, with high average order values.", "opportunity_availability": "Application through Impact with brand approval.", "ugc_evidence": "A conventional network affiliate program; creator guides list YETI among outdoor influencer programs, but no structured UGC track is evidenced on a fetched brand page."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Baleaf Sports', 'https://www.baleaf.com', 'Direct-to-consumer activewear brand for gym, yoga, running and everyday training. Its own Baleaf Community page runs the affiliate program directly — free to join, open to anyone promoting through social media, websites and blogs, with all products except gift cards commission-eligible; the brand publishes no rate on its own page and third-party network figures conflict, so no rate is recorded.', null, 'published') returning id into bid;
