  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Baleaf Sports Affiliate Program (Baleaf Community)', 'https://www.baleaf.com/pages/baleaf-community', 'https://www.baleaf.com/pages/baleaf-community', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.baleaf.com/pages/baleaf-community', 'official_program_page', 'creator_program', 'The brand''s own community page: ''Baleaf''s affiliate program is for anyone who wants to apply and earn commissions by spreading the love for Baleaf products through your unique channels, such as social media, websites, blogs, and the like.'' Joining is free — ''There are no application fees or minimum sales quotas to worry about'' — and ''Except for gift cards, all products featured on the baleaf website qualify for commissions.'' The brand publishes no commission rate and no earnings-cap statement on the page, so commission_rate is null and commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://compareepc.com/activewear-affiliate-programs/', 'third_party_directory', 'commission_rate_conflict', 'Third-party figures conflict: CompareEPC''s activewear ranking lists Baleaf on Impact at 15%; FlexOffers network data shows a payout of 16% of sales; a MyLead listing shows 10.5% CPS. Because the brand itself publishes no rate and the network figures disagree, no rate is recorded.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 9, 4, 8, 3, '{"compensation": "The brand publishes no rate on its own program page and third-party network figures conflict (10.5%-16%), so no rate is recorded; no cap statement is published.", "contact_access": "No partnerships email is published on the fetched page \u2014 application is through the brand''s community page.", "credibility": "A high-volume value activewear brand widely sold online, though with less brand prestige than the premium labels.", "niche_fit": "Affordable leggings, shorts and workout gear are everyday content for fitness, yoga and running creators \u2014 hauls, reviews and workout outfits.", "opportunity_availability": "Free to join with no application fees or minimum sales quotas, per the brand''s own page.", "ugc_evidence": "The brand''s community page recruits affiliates, product testers and ''motivators'' and names social media among the promotion channels \u2014 a genuine creator-facing program, though without a published rate."}'::jsonb);
