  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/rhone/', 'third_party_directory', 'affiliate_program', 'Lasso''s program listing reports the Rhone affiliate program at ''5% Per Sale'' with a 30-day cookie, categorises it under Fashion, and its join link routes to Pepperjam (id.pepperjam.com) — the program''s network route. No earnings-cap statement is published, so commission_cap is unknown.', 'publicly_reported', now());
