  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 11, 9, 4, 7, 5, '{"compensation": "Published figures conflict (5% flat per Lasso versus 5-10% per Shopper) and the brand publishes no rate on a fetched page, so no rate is recorded; no cap statement is published.", "contact_access": "No partnerships email is published in the fetched sources \u2014 joining is through the Pepperjam application.", "credibility": "An established premium men''s performance apparel brand with national retail presence.", "niche_fit": "Premium men''s activewear bridges fitness and fashion content \u2014 training gear, work-to-workout outfits and menswear styling.", "opportunity_availability": "Apply through Pepperjam with brand approval, per the directory join route.", "ugc_evidence": "A conventional network affiliate program pitched at fashion and fitness publishers; no dedicated creator track is evidenced in the fetched sources."}'::jsonb);
