  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 12, 11, 4, 6, 4, '{"compensation": "5% per sale, agreed by two independent directory listings for the Rakuten program \u2014 a modest rate on premium basics; one older aggregator shows 2.8%, noted in evidence. No cap statement is published.", "contact_access": "No partnerships email is published in the fetched sources \u2014 joining is through the Rakuten application.", "credibility": "An established New York direct-to-consumer menswear brand, headquartered in New York per Kochava''s media index.", "niche_fit": "Premium basics \u2014 underwear, socks, tees and tech fabrics \u2014 are steady menswear and everyday-style creator content.", "opportunity_availability": "Apply through Rakuten Advertising; one listing notes the brand ''only works with a limited number of high-quality sites'', so approval is selective.", "ugc_evidence": "A conventional network affiliate program; the brand separately runs creator partnerships with named discount codes, though no public UGC track is evidenced in the fetched sources."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('American Barbell', 'https://americanbarbell.com', 'High-performance strength equipment manufacturer — Olympic bars, dumbbells, plates, kettlebells, racks and rigs trusted by premier health clubs, universities and professional athletes. Its affiliate program runs on Awin: the brand''s own merchant profile promises competitive commissions on individual and commercial equipment with an average order value over $400 and a 90-day cookie, but publishes no percentage.', 'United States', 'published') returning id into bid;
