  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://ui.awin.com/merchant-profile/89095.', 'https://ui.awin.com/merchant-profile/89095', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'American Barbell Affiliate Program (Awin)', 'https://ui.awin.com/merchant-profile/89095', 'https://ui.awin.com/merchant-profile/89095', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/89095', 'network_profile', 'affiliate_program', 'The brand''s own Awin merchant profile: ''As an American Barbell affiliate, you''ll have the opportunity to promote best-in-class strength and conditioning equipment while earning competitive commissions on every sale you refer. Our average order value is over $400, and affiliates can earn a generous commission on both individual and commercial equipment purchases.'' Attribution period (cookie length) is 90 days. The profile explicitly welcomes partners: ''Whether you''re an industry pro, content creator, or gym owner, we welcome bold ideas and strategic partnerships.'' The profile publishes no percentage and no earnings-cap statement, so commission_rate is null and commission_cap is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 11, 9, 4, 7, 4, '{"compensation": "No percentage is published on the brand''s Awin profile \u2014 ''competitive commissions'' only \u2014 so no rate is recorded; the $400+ average order value and 90-day cookie mean even a modest rate pays well per sale. No cap statement is published.", "contact_access": "No partnerships email is published on the fetched Awin profile \u2014 joining is through the network application, with dedicated support promised after joining.", "credibility": "A long-established performance equipment manufacturer trusted by premier health clubs, universities and professional athletes, per its Awin profile.", "niche_fit": "Premium barbells and home-gym equipment are core content for strength, home-gym and equipment-review creators, with very high ticket sizes.", "opportunity_availability": "Open application through Awin with brand approval.", "ugc_evidence": "The Awin profile names content creators among its welcomed partner types and offers marketing assets and dedicated support, though it is a conventional affiliate profile rather than a structured UGC campaign track."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('SWAG Golf', 'https://swag.golf', 'Limited-edition golf gear and apparel brand — headcovers, accessories and apparel with a cult following among golfers. Its own affiliate program page runs through CJ Affiliate: up to 10% commission under a tiered structure with a 60-day cookie, so no single rate is recorded.', 'United States', 'published') returning id into bid;
