  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'CJ Affiliate', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://swag.golf/pages/swag-golf-affiliate-program.', 'https://swag.golf/pages/swag-golf-affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'SWAG Golf Affiliate Program (CJ Affiliate)', 'https://swag.golf/pages/swag-golf-affiliate-program', 'https://swag.golf/pages/swag-golf-affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://swag.golf/pages/swag-golf-affiliate-program', 'official_program_page', 'affiliate_program', 'The brand''s own affiliate page: ''As an affiliate, you''ll earn commission by sharing swag.golf, the first destination for exclusive, limited edition golf gear'' — program perks list ''Up to 10% Commission'' under a ''Tiered structure [that] rewards top performers with bigger payouts'' and a ''60-Day Cookie Duration'', and joining requires an active CJ publisher account. Because the brand publishes only a tiered ''up to'' ceiling rather than a single rate, commission_rate is null. No earnings-cap statement is published, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 20, 11, 9, 4, 7, 3, '{"compensation": "The brand publishes only a tiered ''up to 10%'' ceiling, so no single rate is recorded; the 60-day cookie is generous for the category. No cap statement is published.", "contact_access": "No partnerships email is published on the fetched page \u2014 joining is through the CJ publisher account and application.", "credibility": "A cult limited-edition golf brand with strong drop culture, though far smaller than the major golf equipment names.", "niche_fit": "Limited-edition headcovers and golf apparel map to golf creator content \u2014 bag tours, drop hauls and course vlogs \u2014 a narrower niche than general fitness.", "opportunity_availability": "Open to CJ publishers with brand approval, per the brand''s own program page.", "ugc_evidence": "A conventional network affiliate program aimed at golf publishers; the brand''s drop-driven social culture is creator-friendly, but no structured UGC track is evidenced on the fetched page."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Inno Supps', 'https://www.innosupps.com', 'Inno Supps sells natural, third-party-tested supplements (fat burners, sleep, gut health, performance) direct to consumers, and runs two partner programs: a website Affiliate Program paying link-based commissions and a TikTok Shop Program as an extra channel.', 'United States', 'published') returning id into bid;
