  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Inno Supps Affiliate Program', 'https://www.innosupps.com/pages/affiliates', 'https://www.innosupps.com/pages/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.innosupps.com/pages/affiliates', 'brand_website', 'affiliate_program', 'Inno Supps'' own affiliate page, fetched first-hand, headlines ''Join and earn uncapped commissions'' — an explicit no-cap earnings statement on the brand''s own page, so commission_cap is uncapped. The page runs two programs: the website Affiliate Program (personalized link, commission on website sales) and a TikTok Shop Program; the website program is the recorded route in and TikTok Shop is only an extra channel. Perks include free products, affiliate challenges and a private Discord community. No creator-count data is published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.innosupps.com/pages/affiliates', 'brand_terms', 'commission_rate_conflict', 'No single commission rate is published consistently: the brand''s older Refersion portal showed a 12.5% base ambassador commission via promo code (links not eligible, minimum 5 sales/month), the brand page''s earnings calculator uses a 20% example for the website program, and the program terms (updated September 2026) state each affiliate''s rate is set individually in the dashboard on Social Snowball. Because the published figures conflict, commission_rate is null.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 18, 16, 8, 9, 4, '{"compensation": "Verified uncapped commissions on the brand''s own page; the rate itself is set per affiliate in the dashboard and published figures conflict (12.5% vs 20%), so the rate is honestly null.", "contact_access": "Application runs through the brand''s own affiliate page; no public partnerships email was published on the fetched page.", "credibility": "Established DTC supplement brand with third-party-tested, doctor-backed positioning; rates being dashboard-set rather than published costs a point.", "niche_fit": "Mainstream supplement line (sleep, gut, fat burn, performance) with heavy short-form video marketing \u2014 a strong fit for health and wellness creators.", "opportunity_availability": "Both programs are live and joinable now from the brand page.", "ugc_evidence": "The brand recruits creators directly on its own affiliate page, with a private affiliate Discord, challenges and free product for content creation."}'::jsonb);
