  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://globalhealing.com/pages/affiliates', 'brand_website', 'affiliate_program', 'Global Healing''s own affiliates page, fetched in full, publishes a 10% commission on referred sales, run through Everflow (apply at globalhealing.everflowclient.io), free to join, with a $50 Everflow balance withdrawal threshold. The page prints the contact affiliates@globalhealing.com and names an affiliate specialist. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 14, 13, 14, 9, 5, '{"compensation": "10% commission published by the brand; no cap statement published, so the cap is honestly unknown.", "contact_access": "A named affiliate specialist and a published affiliates@ email on the brand''s own page \u2014 among the most accessible contacts in this batch.", "credibility": "Long-established natural health brand (Dr. Edward Group) with its own manufacturing and a long-running direct store.", "niche_fit": "Detox, gut and plant-based wellness formulas fit natural-health, clean-living and supplement-review creators well.", "opportunity_availability": "Program is live and joinable now via the Everflow application link.", "ugc_evidence": "A formal affiliate program on Everflow with terms published on the brand''s own page, open to promoters and creators."}'::jsonb);
