  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'brand direct', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://ketochow.shop/affiliate-program.', 'https://ketochow.shop/affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Keto Chow Affiliate Program', 'https://ketochow.shop/affiliate-program', 'https://ketochow.shop/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ketochow.shop/affiliate-program', 'brand_website', 'affiliate_program', 'Keto Chow''s own affiliate page, fetched first-hand, publishes a 10% commission on every referred order, paid monthly, and states creator eligibility (over 5,000 followers and over 2% engagement). The page prints the contact orders@ketochow.xyz. The brand''s separate loyalty/referral scheme pays store credit and is NOT the recorded route — the affiliate program pays cash commission. Third-party ''up to 20%'' claims conflict with the brand''s own 10% and are not credited. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 14, 13, 10, 7, 4, '{"compensation": "10% on every referred order published by the brand, paid monthly; no cap statement, so the cap is unknown.", "contact_access": "A contact email is printed on the affiliate page itself, though it is an orders inbox rather than a partnerships desk.", "credibility": "Long-running keto brand with a loyal community; smaller than the national supplement names in this batch.", "niche_fit": "Keto meal shakes are a focused niche \u2014 excellent for keto and low-carb creators, narrower for general food creators.", "opportunity_availability": "Program is live, but the 5,000-follower and 2%-engagement gates limit who can join.", "ugc_evidence": "The brand''s own affiliate page speaks directly to creators with stated follower and engagement requirements."}'::jsonb);
