  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Just Ingredients Creator Program', 'https://justingredients.com/pages/creator-program', 'https://justingredients.com/pages/creator-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://justingredients.com/pages/creator-program', 'brand_website', 'affiliate_program', 'Just Ingredients'' own Creator Program page, fetched first-hand, states ''Must have 10,000 followers to apply'' and routes applications through its Superfiliate portal (justingredients.superfiliate.com). The page publishes no commission percentage, so commission_rate is null. The brand also offers a TikTok Shop creator lane, which is an extra channel only — the Superfiliate Creator Program is the recorded route in. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 16, 8, 8, 6, 4, '{"compensation": "No commission percentage is published on the program page, so the rate is honestly null and compensation scores low until terms are shared in the portal.", "contact_access": "Application runs through the brand''s Creator Program page into Superfiliate; no public partnerships email was published on the fetched page.", "credibility": "Established clean-products brand with a large organic following; unpublished rates cost a point.", "niche_fit": "Clean-ingredient protein and electrolytes are a strong fit for wellness, mom and clean-living creators.", "opportunity_availability": "Program is live, but the 10,000-follower minimum shuts out smaller creators.", "ugc_evidence": "A dedicated Creator Program with its own brand page and application portal \u2014 clear evidence the brand works with creators directly."}'::jsonb);
