  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'ActivatedYou Affiliate Program', 'https://ui.awin.com/merchant-profile/23033', 'https://ui.awin.com/merchant-profile/23033', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/23033', 'network_profile', 'affiliate_program', 'Awin''s own merchant profile for ActivatedYou lists a default commission of 8% for new customers and 4% for returning customers with a 30-day cookie; the 8% new-customer default is recorded. Other sources conflict (FlexOffers up to 6.4%, a shopping directory at 13.3%, and a brand ambassador email citing 20%), and those conflicts are documented here rather than credited. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'publicly_reported', now());
