  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/manukora/', 'affiliate_directory', 'affiliate_program', 'LinkClicky''s program listing, fetched first-hand, states Manukora''s affiliate program runs on Impact at 10% per sale with applications through app.impact.com; the listing was last updated in March 2024. A 2026 product review''s affiliate disclosure states an 8% commission, which conflicts with the 10% listing — because the two published figures conflict and neither is the brand''s own page, commission_rate is null with both figures documented here. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'publicly_reported', now());
