  insert into public.brands (name, website, description, country, status) values ('Puffy', 'https://puffy.com', 'Direct-to-consumer mattress and bedroom brand (''America''s most comfortable mattress'') sold through puffy.com. Its own affiliate program page promises uncapped earning potential and routes applications to Impact; the brand publishes no percentage itself, and third-party rate reports conflict widely.', 'United States', 'published') returning id into bid;
