  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', null, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://puffy.com/pages/affiliates-program.', 'https://puffy.com/pages/affiliates-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Puffy Affiliate Program — VERIFIED UNCAPPED (''uncapped earning potential'' on the brand''s own page), via Impact; published rate reports conflict (20% / 8% / 5.65% / flat ~$300–$400), so the rate is unsettled', 'https://puffy.com/pages/affiliates-program', 'https://puffy.com/pages/affiliates-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://puffy.com/pages/affiliates-program', 'official_site', 'affiliate', 'Puffy''s own affiliate program page fetched in full: ''Get paid to promote America''s most comfortable mattress brand and enjoy uncapped earning potential'', with a headed section ''Uncapped Earning Potential — We help you grow so you can maximize your earning potential.'' That explicit uncapped statement on the brand''s own program page makes the commission cap UNCAPPED. Sign-up routes to Impact (app.impact.com). The page publishes no commission percentage.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://puffy.com/pages/affiliates-program', 'listing', 'affiliate', 'Third-party rate reports conflict, so commission_rate is null: Lasso and LinkClicky report 20%, FlexOffers reports 8%, Shopper reports 5.65%, and several roundups report a flat bounty of roughly $300–$400 per sale (cookie reported as 180 days by some sources and 30 days by others). The flat-bounty reports are documented here rather than recorded as a rate.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 14, 18, 10, 7, 5, '{"compensation": "Verified uncapped on the brand''s own page \u2014 the strongest cap evidence in this batch \u2014 but the rate itself is unsettled across conflicting reports, which holds the score below the maximum", "contact_access": "Application routes from the official program page into Impact; no direct affiliate email is published", "credibility": "Established national DTC mattress brand with a long-running, consistently reported affiliate program", "niche_fit": "Mattresses and bedroom products are a proven home-content category with strong review, unboxing and sleep-routine angles", "opportunity_availability": "Network application with approval; not instant or open to all", "ugc_evidence": "A standing network program on Impact promoted from the brand''s own site; no separate creator tier is published"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('HexClad', 'https://hexclad.com', 'Hybrid stainless-steel and nonstick cookware brand (the Gordon Ramsay-endorsed pans) sold direct through hexclad.com. Its own affiliate page recruits creators, bloggers and publishers with ''up to 15% commission'' and routes applications to Awin, where commission groups run from a 6% base to 8–25% for content publishers.', 'United States', 'published') returning id into bid;
