  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://hexclad.com/pages/affiliate.', 'https://hexclad.com/pages/affiliate', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'HexClad Affiliate Program — cookware via Awin; brand page says up to 15% while Awin groups run 6% base / 8–25% content, so the rate is unsettled', 'https://hexclad.com/pages/affiliate', 'https://hexclad.com/pages/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://hexclad.com/pages/affiliate', 'official_site', 'affiliate', 'HexClad''s own affiliate page fetched: it offers ''up to 15% commission'', names creators, bloggers and publishers as target partners with team review of applications, and its GET STARTED links route to Awin. The brand''s separate influencer page states up to 10%. An ''up to'' figure is a rate ceiling, not a settled rate.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/21679', 'listing', 'affiliate', 'HexClad''s Awin merchant profile (21679) publishes commission groups: base 6%, content publishers 8–25%, coupon/deal 2–5%, loyalty 4–8%, with a 14-day cookie. Lasso separately reports 25%. Because the brand page (up to 15%), the influencer page (up to 10%), the Awin groups (6% base, content up to 25%) and Lasso (25%) do not settle on one rate, commission_rate is null with the structure documented here. No earnings-cap statement is published, so the cap is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 16, 12, 10, 8, 5, '{"compensation": "Content publishers can reach strong rates on Awin (8\u201325%), but the published figures conflict across the brand''s own pages, so compensation is scored on the unsettled evidence; no cap statement exists", "contact_access": "Application via the official affiliate page into Awin, with team review; no direct affiliate email is published", "credibility": "Major national cookware brand with celebrity-chef endorsement and wide retail presence", "niche_fit": "Premium hybrid cookware is one of the most demonstrable kitchen products \u2014 cooking demos, durability tests and chef content are natural UGC", "opportunity_availability": "Open application through a major network, subject to brand approval", "ugc_evidence": "The brand''s own affiliate page explicitly recruits creators, bloggers and publishers, and a separate influencer route exists"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Our Place', 'https://fromourplace.com', 'Los Angeles cookware brand behind the Always Pan, Perfect Pot and Wonder Oven, sold direct through fromourplace.com. It runs an open affiliate program through Impact and PepperJam (Ascend) with no follower minimum, reported at 10% commission, alongside gifting and paid creator partnerships.', 'United States', 'published') returning id into bid;
