  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.bravodm.com/brands/compare/our-place-vs-greatjones.', 'https://fromourplace.com', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Our Place Affiliate Program — Always Pan cookware via Impact + PepperJam, reported 10%, no follower minimum', 'https://fromourplace.com', 'https://www.bravodm.com/brands/compare/our-place-vs-greatjones', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.influencergiftform.com/blog/brands-looking-for-ambassadors', 'listing', 'affiliate', 'Our Place''s program is reported consistently by two independent creator-program directories (Influencer Gift Form and BravoDM, both checked October 2026): an open affiliate program via Impact and PepperJam, 10% commission, no follower minimum, with applications reviewed and all promo channels approved on application. The recorded 10% rate rests on that agreeing third-party reporting, so it is marked publicly_reported.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://affi.io/m/our-place', 'official_site', 'affiliate', 'Our Place''s official Affiliate Program Agreement (last updated March 8, 2022) confirms the program runs with PepperJam as the network partner and that the sales commission rate is ''agreed in writing'' per affiliate rather than published in the agreement — consistent with the 10% figure being set inside the network. No earnings-cap statement is published, so the cap is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 15, 13, 9, 8, 5, '{"compensation": "A reported 10% on premium-priced cookware is fair mid-range pay; the figure is third-party reported rather than brand-published, and no cap statement exists", "contact_access": "Application runs through the Impact/PepperJam networks; no direct affiliate email is published", "credibility": "Established, widely covered DTC cookware brand founded in 2019 with growing wholesale distribution", "niche_fit": "Design-led cookware (Always Pan, Wonder Oven) is a staple of kitchen and home UGC with strong aesthetic content potential", "opportunity_availability": "No follower minimum, though applications and promo channels are reviewed before approval", "ugc_evidence": "An open network affiliate program plus documented gifting and paid creator partnerships and a visible seeding program"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Canopy', 'https://getcanopy.co', 'Home beauty-and-wellness device brand — mold-inhibiting humidifiers, filtered showerheads, faucet and bath filters and an air purifier — developed with dermatologists and sold through getcanopy.co. Its Awin affiliate program pays 10% on all sales with a 30-day cookie, bonus opportunities and product samples for select partners.', 'United States', 'published') returning id into bid;
