  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Canopy Affiliate Program — 10% on all sales via Awin, 30-day cookie, product samples for select partners; contact affiliates@getcanopy.co', 'https://ui.awin.com/merchant-profile/92525', 'https://ui.awin.com/merchant-profile/92525', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/92525', 'listing', 'affiliate', 'Canopy''s Awin merchant profile (92525) fetched in full: ''Earn 10% commission on all sales'', bonus opportunities, a 30-day cookie, product samples available for select partners, and affiliate-exclusive sales — signed by the brand''s affiliate contact with the published email affiliates@getcanopy.co. No earnings-cap statement is published, so the cap is unknown. (A different B2B company also named Canopy runs an unrelated referral scheme at referrals.getcanopy.com; it is not this brand and was ignored.)', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/92525', 'listing', 'creator_program', 'The same Awin profile documents the brand''s press strength — Allure ''Best of Beauty'' 2024 for the Portable Humidifier, Harper''s Bazaar Beauty Icon awards for the Filtered Showerhead, Vogue''s best-overall showerhead pick in spring 2025 — and a fast-expanding device line (humidifiers, showerheads, faucet and bath filters, air purifier launched fall 2025), giving creators a steady stream of new products to cover.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 13, 13, 8, 4, '{"compensation": "A published 10% on all sales with bonus opportunities is solid mid-range pay; no cap statement is published", "contact_access": "Published affiliate email (affiliates@getcanopy.co) with a named contact on the program profile, plus the Awin application route", "credibility": "Award-winning brand (Allure, Harper''s Bazaar, Vogue picks) with dermatologist-developed products", "niche_fit": "Humidifiers, filtered showerheads and air purifiers sit at the home \u00d7 beauty/wellness crossover \u2014 highly demonstrable in routine and get-ready content", "opportunity_availability": "Open to Awin publishers with samples reserved for select partners", "ugc_evidence": "A live program on a major network with product samples for select partners and affiliate-exclusive promotions; no dedicated creator tier is published"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Petlab Co.', 'https://thepetlabco.com', 'Fast-growing pet health brand selling dog supplements — including America''s best-selling Probiotic Chew — through thepetlabco.com. Its Awin program advertises 20% commission on new customers, average order value over $50, a 30-day cookie and a dedicated in-house affiliate team, with monthly bonuses and higher tiers for members.', 'United States', 'published') returning id into bid;
