  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/58051', 'listing', 'affiliate', 'PetLab Co.''s Awin merchant profile (58051) fetched in full: ''Huge 20% commission on new customers'', high average order value of over $50, a 30-day cookie, a dedicated in-house affiliate performance team, real-time reporting, and possible monthly bonuses, higher commission tiers and long-term retainers for programme members. The profile also states the brand has helped over 2.6 million dog parents and built more than 6.5 billion social impressions.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/58051', 'listing', 'affiliate', 'Rate-conflict note: Lasso''s program listing reports PetLab Co. at only ''up to 15%'', which conflicts with the 20%-on-new-customers figure on the program''s own Awin profile. Because the published sources conflict, commission_rate is null, with the Awin profile''s 20% new-customer rate documented in the evidence above. No earnings-cap statement is published, so the cap is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 13, 13, 10, 8, 5, '{"compensation": "The programme''s own profile advertises a strong 20% on new customers plus bonuses and tiers, but a conflicting up-to-15% report keeps the settled score mid-range; no cap statement exists", "contact_access": "Application and contact run through the Awin programme profile; no direct affiliate email is published", "credibility": "Self-described 9-figure pet health brand, 2.6M+ customers and America''s best-selling probiotic chew", "niche_fit": "Dog supplements and probiotic chews are a top-performing pet UGC category with clear before/after and routine content", "opportunity_availability": "Open to Awin publishers, with bonuses and higher tiers reserved for programme members", "ugc_evidence": "A live programme on a major network with a dedicated in-house affiliate team and performance assets on request; the brand''s social reach (6.5B impressions) shows heavy creator-led marketing"}'::jsonb);
