  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://neakasa.com/pages/affiliate-program', 'official_site', 'affiliate', 'Neakasa''s own affiliate page fetched: ''More than 8%'' commission, a 30-day cookie and average order value over $140, with application via ShareASale and the published contact affiliate@neakasa.com. The recorded rate is the brand''s published 8% floor. No earnings-cap statement is published (''massive earning potential'' wording is not an explicit no-cap statement), so the cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/37918', 'listing', 'affiliate', 'Neakasa''s Awin profile (37918) reports up to 15% with custom tiers, and the brand''s own affiliate guide cites a 10% base for top publishers and an additional Impact route (ID 20973). The recorded 8% is the floor the brand itself publishes on its program page; higher tiers are network-negotiated rather than a single published rate.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 13, 13, 8, 4, '{"compensation": "A published 8% floor on a $140+ average order is strong per-sale pay, with custom tiers reported to 15%; no cap statement is published", "contact_access": "Published affiliate email (affiliate@neakasa.com) plus application routes on three networks", "credibility": "Established pet-tech brand with a multi-network, terms-published program", "niche_fit": "Self-cleaning litter boxes and pet grooming vacuums are gadget-driven, highly demonstrable pet-tech products", "opportunity_availability": "Open application via ShareASale from the brand''s own page", "ugc_evidence": "A brand-published affiliate program across three networks (ShareASale, Awin, Impact); no dedicated creator tier is published"}'::jsonb);
