  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Loop Earplugs Affiliate Program — via Impact Radius, 7-day cookie, media deck on approval; brand publishes no rate (third parties report 15%)', 'https://www.loopearplugs.com/pages/affiliate-program', 'https://www.loopearplugs.com/pages/affiliate-program', 'unverified', 'ugc');
