  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 15, 9, 10, 8, 5, '{"compensation": "The brand publishes no rate and the short 7-day cookie is weak; a third-party 15% report is documented but not settled, so compensation scores low on evidence", "contact_access": "Application via the official program page into Impact; no direct affiliate email is published", "credibility": "Category-defining earwear brand with global retail presence and sustained press coverage", "niche_fit": "Design-led earplugs for concerts, focus and sleep are a social-native product with a young, content-heavy audience", "opportunity_availability": "Free to join through a major network, subject to approval", "ugc_evidence": "A creator-friendly program on Impact with a media deck supplied on approval; the brand''s marketing is heavily creator-led"}'::jsonb);
