  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/blissy/', 'listing', 'affiliate', 'Lasso''s Blissy program listing fetched in full: 15% per sale, a 45-day cookie, aimed at bloggers and influencers in the sleep niche, with the join link routing to CJ Affiliate signup (signup.cj.com) and approval typically within a few days. TrakAff independently agrees on 15% per sale and the 45-day cookie, so the 15% rate is recorded as publicly_reported. No earnings-cap statement is published, so the cap is unknown.', 'publicly_reported', now());
