  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Pupford Creator Program — affiliate perks, product gifting and campaigns via the brand''s own Collaborate page; published rate reports conflict (8% / up to 15% / 5–10%), so the rate is unsettled', 'https://pupford.com/pages/collab', 'https://pupford.com/pages/collab', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://pupford.com/pages/collab', 'official_site', 'creator_program', 'Pupford''s own ''Collaborate With Us'' page fetched: ''Become a Pupford Creator — as a creator, you''ll get access to affiliate perks, product gifting, and exclusive campaign opportunities'', with an Apply Now route and member login. That is the brand''s own creator program, which qualifies it under the directory rule. (The brand''s separate Dog Trainers Program is a professional discount scheme, not the creator route, and was not used.)', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/pupford/', 'listing', 'affiliate', 'Third-party rate reports conflict, so commission_rate is null: Dogster''s dog-training program roundup and Lasso''s Pupford LLC listing report 8% per sale, Lasso''s main Pupford listing reports up to 15% with a 14-day cookie, and Shopper reports 5–10%. No earnings-cap statement is published, so the cap is unknown.', 'publicly_reported', now());
